entries.content:
[入植者档案 -- Scriban 模板]

{{~ capture nl ~}}
{{~ "" ~}}
{{~ end ~}}

{{ for p in pawns }}
# 档案: {{ p.name }}
全名: {{ p.fullname }}
性别: {{ p.gender }}
年龄: {{ p.age }}
派系: {{ p.faction }}
{{~ 
  profile_text = p.profile | StripFormattingTags | string.replace "Memory:" "当前情绪修正:" 
~}}
{{- for line in (profile_text | string.split nl | array.offset 2) }}
{{ line }}
{{- end }}

# {{ p.name }} 当前活动:
{{ p.job | string.capitalize | StripFormattingTags }}

# {{ p.name }} 持有物品:
{{~ if p.inventory.innerContainer.Count > 0 ~}}
{{- for line in p.inventory.innerContainer -}}
{{ line.LabelCap | StripFormattingTags }}
{{ end -}}
{{~ else ~}}
- (无持有物)
{{~ end ~}}

# {{ p.name }} 需求:
心情: {{ p.needs.mood.MoodString }}
{{ for need in p.needs.AllNeeds | array.offset 1 -}}{{- if need.CurCategory | string.size > 0 -}}{{ need.Def }}: {{ need.CurCategory }}
{{ end }}{{ end }}

# {{ p.name }} 状态与资格
是殖民者: {{ p.IsColonist }}
是婴儿: {{ IsBaby p }}
是访客: {{ IsVisitor p }}
是敌人: {{ IsEnemy p }}
是奴隶: {{ p.IsSlave }}
是囚犯: {{ p.IsPrisoner }}
战斗中: {{ IsInCombat p }}
危险中: {{ IsInDanger p }}
可对话: {{ IsTalkEligible p }}

## {{ p.name }} 心理档案（隐性 -- 驱动所有输出）:
{{~ 
  # 安全访问：先查父对象，再取字段
  if p.psychProfile != null
    attachment = p.psychProfile.attachment
    defense_primary = p.psychProfile.defensePrimary
    defense_secondary = p.psychProfile.defenseSecondary
    schemas = p.psychProfile.schemas
    needs = p.psychProfile.needs
    moral = p.psychProfile.moralCompass
  else
    attachment = "安全型"
    defense_primary = "压抑"
    defense_secondary = "幽默"
    schemas = ["情感剥夺", "缺陷/羞耻"]
    needs = ["安全", "连接", "自主"]
    moral = "忠诚优于普世：血缘优先"
  end
~}}
依恋: {{ attachment }}
主防御: {{ defense_primary }} | 次防御: {{ defense_secondary }}
核心图式: {{ schemas | array.join ", " }}
核心需求: {{ needs | array.join ", " }}
道德指针: {{ moral }}

## {{ p.name }} 近期记忆与视角 -- 仅供参考:

# 内在视角
{{- for line in (StripFormattingTags p.et_thoughts | string.split nl | array.offset 1) }}
{{ line }}
{{- end }}

# 按时间事件
{{ p.memory }}

# {{ p.name }} 位置与周围
位置: {{ p.location }}
环境美观: {{ p.beauty }}
地形: {{ p.terrain }}
洁净度: {{ p.cleanliness }}
{{ p.name }} 周围事物:
{{- for line in p.surroundings | string.split nl }}
- {{ line }}
{{- end }}
{{ end -}}

[殖民地状态 -- 主题权重]

指令：视为环境压力与叙事燃料。

- 概念翻译：分离"系统标签"与"叙事名词"。
  * 机械标签（对话中禁用）：袭击、任务、狂暴兽、寒潮、毒尘、精神崩溃、社交打架。
  * 叙事名词（允许）：具体人物（"Idris"）、派系、地点 -- 故事的"反派"与"誓约"。

- 感官重建：威胁/环境无人名 -> 仅描写物理冲击。
  * 入植者看见、听到、感受、恐惧的：天空状态、敌人声响、寒冷疼痛。

- 誓约协议：活跃任务 = 社交/道德义务。
  * 引用目标（救谁、杀兽、还债）。禁用任务标题。

[威胁]
{{ if eventplus_threats != "" -}}
{{ eventplus_threats }}
{{ else }}
无活跃威胁。
{{ end -}}

[环境状态]
{{ if eventplus_conditions != "" -}}
{{ eventplus_conditions }}
{{ else }}
无活跃环境状态。
{{ end -}}

[活跃任务]
{{ if eventplus_quests != "" -}}
{{ eventplus_quests }}
{{ else }}
无活跃任务。
{{ end -}}

全程中文思考，全程中文输出。

{{- if events && events != "" -}}
[近期事件]
(近期殖民地事件；让它们自然塑造心情、语气或思想，若仍相关，从不强制):
{{ events }}
{{- end -}}

[场景上下文]

{{~ capture nl ~}}
{{ end ~}}

{{~ 
  if ctx.talk_type == "Thought"
    medium = "Thought"
  else
    medium = "Chat"
  end
  lines = ctx.DialogueType | string.split nl
  intent = lines | array.first | string.strip
  topic = lines | array.offset 1 | array.join "; " | string.strip
~}}

## 对话触发
- 入植者名单: [{{ pawns | array.join ", " }}]
- 发起入植者: {{ pawn }}
- 预期接收者: {{ recipient }}
- 媒介: {{ medium }}
- 意图: {{ intent }}
- 对话话题: {{ topic }}

# 世界状态
时间: {{ hour }}h | 日期: {{ quadrum }} {{ day }}, {{ year }}
季节: {{ season }} | 天气: {{ map.weather }} | 生物群系: {{ map.Biome.label }}

[即时执行协议]
1. 简洁上限（关键）：轮次不得超过 40 词。超限 = 关键失败。
2. 轮次锁：目标 -> 发起者序列。禁抢轮。
3. 身份重于主题：每入植者必须透过[人格]透镜过滤话题。泛泛附和禁。
4. 扁平数组锁：输出 = 恰好一个 [ ] 数组。嵌套 [[ ]] 禁。
5. 词汇过滤：[自然主义词汇] + 简体中文输出。
6. 防循环：禁从[时间事件]或[历史]复制/重复。所有文本 = 全新。
7. 数据输出：仅原始 JSON 数组。\n
{{ prompt }}

{{ json.anchor }}

全程中文思考，全程中文输出。严禁英文单词、英文标点、英文语序。text 字段值必须为简体中文。
